package com.neml.badminton.repository;import com.neml.badminton.entity.ChampionshipBrandingConfiguration;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;import java.util.*;
public interface ChampionshipBrandingConfigurationRepository extends JpaRepository<ChampionshipBrandingConfiguration,UUID>{Optional<ChampionshipBrandingConfiguration> findFirstByChampionshipIdOrderByConfigurationVersionDesc(UUID championshipId);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select c from ChampionshipBrandingConfiguration c where c.championship.id=:cid and c.configurationVersion=(select max(x.configurationVersion) from ChampionshipBrandingConfiguration x where x.championship.id=:cid)")Optional<ChampionshipBrandingConfiguration> findLatestForUpdate(@Param("cid")UUID championshipId);}
